import { SupabaseRuntimeRepository } from './supabase_repository';
import { ToolRegistry } from './tool_registry';
import { registerAccountsTools } from './accounts_tools';
import { findCollectionWorkDue } from './accounts_collections';
import { GroqProvider } from './groq_provider';
import { parseAccountsDecision } from './accounts_decision';
import { WhatsAppCollectionReminderDelivery } from './collection_channel';
export async function runAccountsAgent(repo:SupabaseRuntimeRepository,env:any,organisationId:string,agent:any,scope?:{invoiceId?:string}){
 const work=await findCollectionWorkDue(repo,organisationId),selected=scope?.invoiceId?work.filter((x:any)=>x.id===scope.invoiceId):work;
 const run:any=await repo.insert('agent_runs',organisationId,{agent_id:agent.id,session_id:null,provider:null,model:null,status:'started',tools_invoked:[]});
 try{const registry=new ToolRegistry();registerAccountsTools(registry,repo,organisationId,agent.id);const outputs=[];
  for(const invoice of selected.slice(0,20)){
   if(invoice.stage==='final_review'){const action:any=await repo.insert('agent_actions',organisationId,{agent_id:agent.id,requested_by:null,tool_key:'sendPaymentReminder',risk:'approval_required',status:'approval_pending',input_payload:{invoice_id:invoice.id,stage:invoice.stage},payload_sha256:'accounts-final-review',idempotency_key:`${invoice.id}:final_review`});await repo.insert('approvals',organisationId,{agent_action_id:action.id,requested_by:null,payload_sha256:'accounts-final-review'});await repo.insert('collection_activity',organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,activity_type:'approval_requested',stage:invoice.stage,metadata:{agent_id:agent.id}});outputs.push({invoiceId:invoice.id,stage:invoice.stage,status:'approval_required'});continue;}
   let message=`Payment reminder for invoice ${invoice.invoice_number}, outstanding balance ${invoice.outstanding_balance} ${invoice.currency}, due ${invoice.due_date}.`;
   if(env.AI_API_KEY){const completion=await new GroqProvider(env.AI_API_KEY,env.AI_MODEL).completeStructured({system:'Return JSON with decision, confidence, approvalRequired, message, reason. Use only supplied invoice facts. Never calculate or alter financial facts. Do not invent payment instructions, fees, legal consequences, or amounts.',messages:[{role:'user',content:message}],schema:'AccountsDecision'});const parsed=parseAccountsDecision(completion.structuredOutput);message=parsed.message??message;await repo.insert('ai_usage_events',organisationId,{agent_id:agent.id,provider:completion.provider,model:completion.model,input_tokens:completion.usage?.inputTokens??null,output_tokens:completion.usage?.outputTokens??null,request_count:1});}
   await repo.insert('collection_activity',organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,activity_type:'reminder_prepared',stage:invoice.stage,metadata:{agent_id:agent.id}});await repo.insert('audit_logs',organisationId,{actor_user_id:null,event_type:'accounts_reminder_prepared',entity_type:'invoice',entity_id:invoice.id,metadata:{agent_id:agent.id,stage:invoice.stage}});let delivery:any={status:'prepared'};const policy:any=(await repo.list('collection_policies',organisationId))[0]??{};if(policy.automatic_sending_enabled&&invoice.stage!=='final_review'){delivery=await new WhatsAppCollectionReminderDelivery(repo).send({organisationId,contactId:invoice.contact_id,invoiceId:invoice.id,message,agentId:agent.id,env});if(delivery.status==='sent'){await repo.insert('collection_activity',organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,activity_type:'reminder_sent',stage:invoice.stage,metadata:{agent_id:agent.id,channel:'whatsapp'}});await repo.insert('audit_logs',organisationId,{actor_user_id:null,event_type:'accounts_reminder_sent',entity_type:'invoice',entity_id:invoice.id,metadata:{agent_id:agent.id,stage:invoice.stage,channel:'whatsapp'}});}else if(delivery.status==='failed')await repo.insert('collection_activity',organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,activity_type:'reminder_failed',stage:invoice.stage,metadata:{agent_id:agent.id,reason:delivery.reason}});}outputs.push({invoiceId:invoice.id,stage:invoice.stage,status:delivery.status,message});
  }
  await repo.updateRun(organisationId,run.id,{status:'succeeded',tools_invoked:outputs,finished_at:new Date().toISOString()});return {runId:run.id,items:outputs};
 }catch(error){await repo.updateRun(organisationId,run.id,{status:'failed',error_code:error instanceof Error?error.message:'ACCOUNTS_RUN_FAILED',finished_at:new Date().toISOString()});throw error;}
}
