import { Hono } from 'hono'; import { AppEnv, ApiError } from '../api_types'; import { authMiddleware } from '../middleware/auth'; import { MetaWhatsAppCloudProvider, WhatsAppProviderError } from '../whatsapp/provider'; import { runEmailAgent } from '../email/email_dispatcher'; import { runVoiceReceptionist } from '../voice/voice_dispatcher';
export const inboxRoutes=new Hono<AppEnv>(); inboxRoutes.use('*',authMiddleware);
inboxRoutes.get('/crm/contacts',async c=>c.json({contacts:await c.get('runtimeRepository').list('crm_contacts',c.get('agentContext').organisationId)}));
inboxRoutes.post('/crm/contacts',async c=>{const x=c.get('agentContext'),body=await c.req.json<any>(),fullName=String(body.full_name??'').trim();if(!fullName)throw new ApiError('VALIDATION_ERROR','Contact name is required.');return c.json({contact:await c.get('runtimeRepository').insert('crm_contacts',x.organisationId,{full_name:fullName,email:typeof body.email==='string'?body.email.trim()||null:null,phone:typeof body.phone==='string'?body.phone.trim()||null:null,whatsapp_number:typeof body.whatsapp_number==='string'?body.whatsapp_number.trim()||null:null,company_name:typeof body.company_name==='string'?body.company_name.trim()||null:null,lifecycle_status:'new',source:'manual',active:true})},201);});
inboxRoutes.get('/crm/contacts/:id',async c=>{const x=c.get('agentContext'),rows=await c.get('runtimeRepository').list('crm_contacts',x.organisationId,{id:c.req.param('id')});if(!rows[0])throw new ApiError('NOT_FOUND','Contact not found.');return c.json({contact:rows[0]});});
inboxRoutes.patch('/crm/contacts/:id',async c=>{const x=c.get('agentContext'),body=await c.req.json<{full_name?:string;email?:string;company_name?:string;lifecycle_status?:string}>(),values:any={};for(const key of ['full_name','email','company_name','lifecycle_status'] as const)if(typeof body[key]==='string')values[key]=body[key]!.trim();if(!Object.keys(values).length)throw new ApiError('VALIDATION_ERROR','No editable fields supplied.');return c.json({contact:await c.get('runtimeRepository').update('crm_contacts',x.organisationId,c.req.param('id'),values)});});
inboxRoutes.get('/inbox/conversations',async c=>c.json({conversations:await c.get('runtimeRepository').list('unified_conversations',c.get('agentContext').organisationId)}));
inboxRoutes.get('/inbox/conversations/:id/messages',async c=>c.json({messages:await c.get('runtimeRepository').list('unified_messages',c.get('agentContext').organisationId,{conversation_id:c.req.param('id')})}));
inboxRoutes.post('/inbox/conversations/:id/messages',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),conversationId=c.req.param('id'),body=await c.req.json<{text?:string}>(),text=body.text?.trim();if(!text||text.length>4000)throw new ApiError('VALIDATION_ERROR','Reply must contain between 1 and 4000 characters.');const rows=await r.list('unified_conversations',x.organisationId,{id:conversationId,channel_key:'whatsapp'});if(!rows[0])throw new ApiError('NOT_FOUND','Conversation not found.');const conversation:any=rows[0],integrations=await r.list('organisation_integrations',x.organisationId,{provider:'meta_whatsapp',status:'connected'}),integration:any=integrations[0],contacts=await r.list('crm_contacts',x.organisationId,{id:conversation.contact_id}),contact:any=contacts[0];if(!integration?.phone_number_id)throw new ApiError('INTERNAL_ERROR','WhatsApp integration is not connected.',503);if(!contact?.whatsapp_number)throw new ApiError('VALIDATION_ERROR','Conversation recipient is unavailable.');const pending:any=await r.insert('unified_messages',x.organisationId,{conversation_id:conversationId,channel_key:'whatsapp',direction:'outbound',recipient:contact.whatsapp_number,content:text,message_type:'text',delivery_status:'pending',human_generated:true});try{const sent=await new MetaWhatsAppCloudProvider(c.env.META_WHATSAPP_ACCESS_TOKEN??'',c.env.META_GRAPH_API_VERSION??'v23.0').sendText(integration.phone_number_id,contact.whatsapp_number,text);const updated=await r.update('unified_messages',x.organisationId,pending.id,{external_message_id:sent.providerMessageId,delivery_status:sent.status});await r.update('unified_conversations',x.organisationId,conversationId,{last_activity_at:new Date().toISOString()});return c.json({message:updated});}catch(error){const code=error instanceof WhatsAppProviderError?error.code:'WHATSAPP_SEND_FAILED';await r.update('unified_messages',x.organisationId,pending.id,{delivery_status:'failed',metadata:{error_code:code}});throw new ApiError('INTERNAL_ERROR',code,503);}});
inboxRoutes.post('/inbox/conversations/:id/takeover',async c=>{const x=c.get('agentContext');return c.json({conversation:await c.get('runtimeRepository').update('unified_conversations',x.organisationId,c.req.param('id'),{status:'human_takeover',assigned_human:x.userId})});});
inboxRoutes.post('/inbox/conversations/:id/handback',async c=>{const x=c.get('agentContext');return c.json({conversation:await c.get('runtimeRepository').update('unified_conversations',x.organisationId,c.req.param('id'),{status:'open',assigned_human:null})});});
inboxRoutes.get('/integrations/whatsapp',async c=>{const x=c.get('agentContext'),rows=await c.get('runtimeRepository').list('organisation_integrations',x.organisationId,{provider:'meta_whatsapp'});return c.json({integration:rows[0]?{status:(rows[0] as any).status,phoneNumberId:(rows[0] as any).phone_number_id,displayPhoneNumber:(rows[0] as any).display_phone_number,webhookStatus:(rows[0] as any).webhook_status}:null});});
inboxRoutes.get('/agents/whatsapp',async c=>{const x=c.get('agentContext'),rows=await c.get('runtimeRepository').list('agents',x.organisationId,{agent_type_key:'whatsapp_agent'});return c.json({agent:rows[0]??null});});
inboxRoutes.post('/agents/whatsapp/status',async c=>{const x=c.get('agentContext'),body=await c.req.json<{status?:string}>(),status=body.status;if(status!=='active'&&status!=='paused')throw new ApiError('VALIDATION_ERROR','Status must be active or paused.');const rows=await c.get('runtimeRepository').list('agents',x.organisationId,{agent_type_key:'whatsapp_agent'});if(!rows[0])throw new ApiError('NOT_FOUND','WhatsApp Agent not found.');return c.json({agent:await c.get('runtimeRepository').update('agents',x.organisationId,(rows[0] as any).id,{status})});});
async function emailAgent(r:any,org:string){const rows:any[]=await r.list('agents',org,{agent_type_key:'email_agent'});return rows[0]??r.insert('agents',org,{agent_type_key:'email_agent',display_name:'Email Agent',status:'active',config:{email_policy:{automatic_replies_enabled:false,complaints_escalate:true,sensitive_replies_require_approval:true,default_tone:'professional'}}});}
inboxRoutes.get('/agents/email',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),agent:any=await emailAgent(r,x.organisationId),integration:any=(await r.list('organisation_integrations',x.organisationId,{channel_key:'email'}))[0];return c.json({agent:{id:agent.id,status:agent.status,type:'email_agent',policy:agent.config?.email_policy??{}},integration:integration?{provider:integration.provider,connected:integration.status==='connected',account:integration.account_identity??null,status:integration.status}: {provider:'disconnected',connected:false,status:'disconnected'}});});
inboxRoutes.post('/agents/email/status',async c=>{const x=c.get('agentContext'),body=await c.req.json<any>(),r=c.get('runtimeRepository');if(!['active','paused'].includes(body.status))throw new ApiError('VALIDATION_ERROR','Status must be active or paused.');const agent:any=await emailAgent(r,x.organisationId);await r.insert('audit_logs',x.organisationId,{actor_user_id:x.userId,event_type:'email_agent_status_changed',entity_type:'agent',entity_id:agent.id,metadata:{status:body.status}});return c.json({agent:await r.update('agents',x.organisationId,agent.id,{status:body.status})});});
inboxRoutes.get('/agents/email/policy',async c=>{const x=c.get('agentContext'),agent:any=await emailAgent(c.get('runtimeRepository'),x.organisationId);return c.json({policy:agent.config?.email_policy??{}});});
inboxRoutes.patch('/agents/email/policy',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),body=await c.req.json<any>(),agent:any=await emailAgent(r,x.organisationId);const policy={automatic_replies_enabled:body.automatic_replies_enabled===true,complaints_escalate:body.complaints_escalate!==false,sensitive_replies_require_approval:body.sensitive_replies_require_approval!==false,default_tone:['professional','friendly','formal'].includes(body.default_tone)?body.default_tone:'professional'};await r.insert('audit_logs',x.organisationId,{actor_user_id:x.userId,event_type:'email_agent_policy_updated',entity_type:'agent',entity_id:agent.id,metadata:{policy}});return c.json({policy:(await r.update('agents',x.organisationId,agent.id,{config:{...(agent.config??{}),email_policy:policy}}) as any).config.email_policy});});
inboxRoutes.post('/agents/email/run',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),body=await c.req.json<any>();const message:any=body.message_id?(await r.list('unified_messages',x.organisationId,{id:body.message_id,channel_key:'email'}))[0]:(await r.list('unified_messages',x.organisationId,{channel_key:'email',ai_processing_status:'not_started'}))[0];if(!message)return c.json({no_work:true});const conversation:any=(await r.list('unified_conversations',x.organisationId,{id:message.conversation_id}))[0],integrationId=conversation?.metadata?.integration_id;if(!conversation||!integrationId)throw new ApiError('NOT_FOUND','Email work item is unavailable.');return c.json(await runEmailAgent(r,c.env,{organisationId:x.organisationId,integrationId,conversationId:conversation.id,messageId:message.id,contactId:conversation.contact_id,trigger:'manual'}),202);});
async function voiceAgent(r:any,org:string){const rows:any[]=await r.list('agents',org,{agent_type_key:'voice_receptionist'});return rows[0]??r.insert('agents',org,{agent_type_key:'voice_receptionist',display_name:'Voice Receptionist',status:'active',config:{voice_policy:{basic_enquiries_enabled:true,human_escalation_enabled:true,appointment_capture_enabled:true,sensitive_requests_escalate:true,default_tone:'professional_friendly'}}});}
inboxRoutes.get('/agents/voice',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),agent:any=await voiceAgent(r,x.organisationId);return c.json({agent:{id:agent.id,status:agent.status,policy:agent.config?.voice_policy??{}},integration:{provider:'disconnected',connected:false,status:'disconnected'}});});
inboxRoutes.post('/agents/voice/status',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),body=await c.req.json<any>();if(!['active','paused'].includes(body.status))throw new ApiError('VALIDATION_ERROR','Status must be active or paused.');const agent:any=await voiceAgent(r,x.organisationId);await r.insert('audit_logs',x.organisationId,{actor_user_id:x.userId,event_type:'voice_agent_status_changed',entity_type:'agent',entity_id:agent.id,metadata:{status:body.status}});return c.json({agent:await r.update('agents',x.organisationId,agent.id,{status:body.status})});});
inboxRoutes.get('/agents/voice/policy',async c=>{const x=c.get('agentContext'),agent:any=await voiceAgent(c.get('runtimeRepository'),x.organisationId);return c.json({policy:agent.config?.voice_policy??{}});});
inboxRoutes.patch('/agents/voice/policy',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),body=await c.req.json<any>(),agent:any=await voiceAgent(r,x.organisationId);const policy={basic_enquiries_enabled:body.basic_enquiries_enabled!==false,human_escalation_enabled:body.human_escalation_enabled!==false,appointment_capture_enabled:body.appointment_capture_enabled!==false,sensitive_requests_escalate:body.sensitive_requests_escalate!==false,default_tone:['professional_friendly','professional','friendly'].includes(body.default_tone)?body.default_tone:'professional_friendly'};await r.insert('audit_logs',x.organisationId,{actor_user_id:x.userId,event_type:'voice_agent_policy_updated',entity_type:'agent',entity_id:agent.id,metadata:{policy}});const updated:any=await r.update('agents',x.organisationId,agent.id,{config:{...(agent.config??{}),voice_policy:policy}});return c.json({policy:updated.config.voice_policy});});
inboxRoutes.post('/agents/voice/run',async c=>{const x=c.get('agentContext'),body=await c.req.json<any>();if(typeof body.callerNumber!=='string'||typeof body.transcript!=='string'||!body.callerNumber.trim()||!body.transcript.trim())throw new ApiError('VALIDATION_ERROR','Caller number and transcript are required.');await voiceAgent(c.get('runtimeRepository'),x.organisationId);return c.json(await runVoiceReceptionist(c.get('runtimeRepository'),c.env,{organisationId:x.organisationId,callerNumber:body.callerNumber,callerName:typeof body.callerName==='string'?body.callerName.slice(0,200):undefined,transcript:body.transcript,trigger:'manual_simulation'}),202);});
