import type { SupabaseRuntimeRepository } from './supabase_repository';
export type TenderInput = { sourceProvider?: string; externalId?: string; reference?: string; title: string; buyer?: string; description?: string; category?: string; location?: string; publishedAt?: string; closingAt?: string; estimatedValue?: number; currency?: string; eligibilitySummary?: string; submissionMethod?: string; sourceUrl?: string; metadata?: Record<string, unknown> };
export function normalizeTender(input: TenderInput) { return { source_provider: input.sourceProvider ?? 'manual', external_id: input.externalId ?? null, reference: input.reference ?? null, title: input.title.trim(), buyer: input.buyer ?? null, description: input.description ?? null, category: input.category ?? null, location: input.location ?? null, published_at: input.publishedAt ?? null, closing_at: input.closingAt ?? null, estimated_value: input.estimatedValue ?? null, currency: input.currency ?? 'ZAR', eligibility_summary: input.eligibilitySummary ?? null, submission_method: input.submissionMethod ?? null, source_url: input.sourceUrl ?? null, metadata: input.metadata ?? {} }; }
export class ManualTenderSourceProvider { constructor(private readonly repo: SupabaseRuntimeRepository) {} async persist(organisationId: string, input: TenderInput) { const value = normalizeTender(input); const existing = value.external_id ? (await this.repo.list('tender_opportunities', organisationId, { source_provider: value.source_provider, external_id: value.external_id }))[0] : null; return existing ? this.repo.update('tender_opportunities', organisationId, (existing as any).id, value) : this.repo.insert('tender_opportunities', organisationId, value); } }
