export type WhatsAppStatus = 'pending'|'sent'|'delivered'|'read'|'failed';
export type WhatsAppErrorCode = 'WHATSAPP_PROVIDER_NOT_CONFIGURED'|'WHATSAPP_PROVIDER_UNAUTHORIZED'|'WHATSAPP_PROVIDER_RATE_LIMITED'|'WHATSAPP_TEMPLATE_REQUIRED'|'WHATSAPP_RECIPIENT_INVALID'|'WHATSAPP_PROVIDER_UNAVAILABLE'|'WHATSAPP_SEND_FAILED';
export class WhatsAppProviderError extends Error { constructor(public readonly code: WhatsAppErrorCode) { super(code); } }
export function statusPrecedence(status: WhatsAppStatus): number { return ({ pending: 0, sent: 1, delivered: 2, read: 3, failed: 4 } as Record<WhatsAppStatus, number>)[status]; }
export function monotonicStatus(current: WhatsAppStatus, incoming: WhatsAppStatus): WhatsAppStatus { if (current === 'read' || (current === 'failed' && incoming !== 'read')) return current; return statusPrecedence(incoming) >= statusPrecedence(current) ? incoming : current; }
export interface WhatsAppProvider { sendText(phoneNumberId: string, to: string, text: string, idempotencyKey?: string): Promise<{ providerMessageId: string; status: WhatsAppStatus }>; parseWebhook(payload: unknown): Array<{ kind: 'message'|'status'; phoneNumberId: string; messageId: string; from?: string; text?: string; type?: string; status?: WhatsAppStatus; timestamp?: string }>; }
export class MetaWhatsAppCloudProvider implements WhatsAppProvider {
 constructor(private readonly token: string, private readonly version = 'v23.0', private readonly fetcher: typeof fetch = fetch) {}
 async sendText(phoneNumberId:string,to:string,text:string):Promise<{providerMessageId:string;status:WhatsAppStatus}>{ if(!this.token)throw new WhatsAppProviderError('WHATSAPP_PROVIDER_NOT_CONFIGURED'); const response=await this.fetcher(`https://graph.facebook.com/${this.version}/${encodeURIComponent(phoneNumberId)}/messages`,{method:'POST',headers:{authorization:`Bearer ${this.token}`,'content-type':'application/json'},body:JSON.stringify({messaging_product:'whatsapp',to,type:'text',text:{body:text}})}); if(response.ok){const body=await response.json() as any;return {providerMessageId:String(body?.messages?.[0]?.id??''),status:'sent'};} if(response.status===401||response.status===403)throw new WhatsAppProviderError('WHATSAPP_PROVIDER_UNAUTHORIZED');if(response.status===429)throw new WhatsAppProviderError('WHATSAPP_PROVIDER_RATE_LIMITED');if(response.status>=500)throw new WhatsAppProviderError('WHATSAPP_PROVIDER_UNAVAILABLE');const body=await response.clone().json().catch(()=>({})) as any;const message=JSON.stringify(body).toLowerCase();if(message.includes('window')||message.includes('template'))throw new WhatsAppProviderError('WHATSAPP_TEMPLATE_REQUIRED');if(message.includes('recipient')||message.includes('phone'))throw new WhatsAppProviderError('WHATSAPP_RECIPIENT_INVALID');throw new WhatsAppProviderError('WHATSAPP_SEND_FAILED'); }
 parseWebhook(payload:any){const out:any[]=[];for(const entry of payload?.entry??[])for(const change of entry?.changes??[])for(const value of [change?.value]){const phone=String(value?.metadata?.phone_number_id??'');for(const m of value?.messages??[])out.push({kind:'message',phoneNumberId:phone,messageId:String(m.id),from:m.from,text:m.type==='text'?m.text?.body:undefined,type:m.type,timestamp:m.timestamp});for(const s of value?.statuses??[])out.push({kind:'status',phoneNumberId:phone,messageId:String(s.id),status:s.status==='read'?'read':s.status==='delivered'?'delivered':s.status==='sent'?'sent':'failed'});}return out;}
}
export function normalizeWhatsAppNumber(value: string): string { return value.trim().replace(/^\+/, '').replace(/[^0-9]/g, ''); }
