import { SupabaseRuntimeRepository } from './supabase_repository'; import { ToolRegistry } from './tool_registry'; import { collectionStage,getCustomerAccount } from './accounts_collections';
const text=(x:any,max:number)=>{if(typeof x!=='string'||!x.trim()||x.length>max)throw new Error('INVALID_ARGUMENT');return x.trim();};
export function registerAccountsTools(registry:ToolRegistry,repo:SupabaseRuntimeRepository,organisationId:string,agentId:string){const read=(name:string,fn:(i:any)=>Promise<unknown>)=>registry.register({name,purpose:name,risk:'automatic',classification:'read',validate:(i:any)=>i??{},execute:async(_context:any,input:any)=>fn(input)} as any);read('getCustomerAccount',i=>getCustomerAccount(repo,organisationId,text(i.contactId,80)));read('getInvoice',async i=>(await repo.list('invoices',organisationId,{id:text(i.invoiceId,80)}))[0]??null);read('listOutstandingInvoices',async()=>{const rows:any[]=await repo.list('invoices',organisationId);return rows.filter(i=>i.status!=='cancelled'&&i.status!=='paid'&&Number(i.total_amount)>0);});read('listOverdueInvoices',async()=>{const rows:any[]=await repo.list('invoices',organisationId),today=new Date().toISOString().slice(0,10);return rows.filter(i=>i.status!=='cancelled'&&i.due_date<today);});read('getPaymentHistory',i=>repo.list('invoice_payments',organisationId,{invoice_id:text(i.invoiceId,80)}));read('getCollectionPolicy',async()=> (await repo.list('collection_policies',organisationId))[0]??null);read('getCollectionActivity',i=>repo.list('collection_activity',organisationId,{invoice_id:text(i.invoiceId,80)}));
 const write=(name:string,execute:(i:any)=>Promise<unknown>)=>registry.register({name,purpose:name,risk:'controlled_agent_write',classification:'write',validate:(i:any)=>i??{},execute:async(_c:any,i:any)=>execute(i)} as any);
 write('addCollectionNote',async i=>{const note=text(i.note,500);return repo.insert('collection_activity',organisationId,{contact_id:i.contactId,invoice_id:i.invoiceId??null,activity_type:'collection_note',metadata:{note,source:'agent',agent_id:agentId}});});write('recordPromiseToPay',async i=>{const note=text(i.note??'customer explicitly committed',300);return repo.insert('promise_to_pay',organisationId,{contact_id:text(i.contactId,80),invoice_id:i.invoiceId??null,promised_amount:i.promisedAmount,promised_date:i.promisedDate,source:'agent_customer_statement',note,status:'active'});});write('requestCollectionsEscalation',async i=>repo.insert('collection_activity',organisationId,{contact_id:i.contactId,invoice_id:i.invoiceId??null,activity_type:'escalation_requested',metadata:{reason:text(i.reason,200),source:'agent',agent_id:agentId}}));write('preparePaymentReminder',async i=>repo.insert('collection_activity',organisationId,{contact_id:i.contactId,invoice_id:i.invoiceId,activity_type:'reminder_prepared',stage:text(i.stage,30),metadata:{message:text(i.message,2000),source:'agent',agent_id:agentId}}));write('sendPaymentReminder',async i=>{const policy:any=(await repo.list('collection_policies',organisationId))[0]??{};if(!policy.automatic_sending_enabled)throw new Error('APPROVAL_REQUIRED');const existing=await repo.list('collection_activity',organisationId,{invoice_id:i.invoiceId,activity_type:'reminder_sent',stage:i.stage});if(existing.length>=Number(policy.maximum_automatic_reminders??2))throw new Error('REMINDER_LIMIT_REACHED');return repo.insert('collection_activity',organisationId,{contact_id:i.contactId,invoice_id:i.invoiceId,activity_type:'reminder_sent',stage:text(i.stage,30),metadata:{message:text(i.message,2000),source:'agent',agent_id:agentId}});});}
