import { Hono } from 'hono'; import { AppEnv, ApiError } from '../api_types'; import { authMiddleware } from '../middleware/auth';
import { runAccountsAgent } from '../agent-runtime/accounts_dispatcher'; import { collectionStage } from '../agent-runtime/accounts_collections'; import { WhatsAppCollectionReminderDelivery } from '../agent-runtime/collection_channel';
export const accountsRoutes=new Hono<AppEnv>(); accountsRoutes.use('*',authMiddleware);
accountsRoutes.get('/accounts/invoices',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),rows:any[]=await r.list('invoices',x.organisationId),payments:any[]=await r.list('invoice_payments',x.organisationId);const by=new Map<string,number>();for(const p of payments)if(p.status==='confirmed')by.set(p.invoice_id,(by.get(p.invoice_id)??0)+Number(p.amount));const today=new Date().toISOString().slice(0,10),q=(c.req.query('q')??'').toLowerCase(),status=c.req.query('status'),contactId=c.req.query('contact_id');return c.json({invoices:rows.map(i=>{const paid=by.get(i.id)??0,balance=Math.max(0,Number(i.total_amount)-paid),overdue=balance>0&&i.due_date<today&&i.status!=='cancelled';return {...i,amount_paid:paid,outstanding_balance:balance,computed_status:overdue?'overdue':balance===0?'paid':i.status};}).filter(i=>(!q||`${i.invoice_number} ${i.notes??''}`.toLowerCase().includes(q))&&(!status||i.computed_status===status)&&(!contactId||i.contact_id===contactId))});});
accountsRoutes.get('/accounts/invoices/:id',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),rows=await r.list('invoices',x.organisationId,{id:c.req.param('id')});if(!rows[0])throw new ApiError('NOT_FOUND','Invoice not found.');return c.json({invoice:rows[0],payments:await r.list('invoice_payments',x.organisationId,{invoice_id:c.req.param('id')}),activity:await r.list('collection_activity',x.organisationId,{invoice_id:c.req.param('id')}),promises:await r.list('promise_to_pay',x.organisationId,{invoice_id:c.req.param('id')})});});
accountsRoutes.get('/crm/contacts/:id/accounts-summary',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),rows:any[]=await r.list('invoices',x.organisationId,{contact_id:c.req.param('id')}),today=new Date().toISOString().slice(0,10);const payments:any[]=await r.list('invoice_payments',x.organisationId,{contact_id:c.req.param('id')}),paid=new Map<string,number>();for(const p of payments)if(p.status==='confirmed')paid.set(p.invoice_id,(paid.get(p.invoice_id)??0)+Number(p.amount));let outstanding=0,overdue=0,overdueCount=0;for(const i of rows){const b=Math.max(0,Number(i.total_amount)-(paid.get(i.id)??0));outstanding+=b;if(b>0&&i.due_date<today&&i.status!=='cancelled'){overdue+=b;overdueCount++;}}return c.json({summary:{invoiceCount:rows.length,totalOutstanding:outstanding,overdueAmount:overdue,overdueInvoiceCount:overdueCount}});});
accountsRoutes.patch('/accounts/invoices/:id',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),body=await c.req.json<any>(),values:any={};for(const key of ['invoice_number','issue_date','due_date','notes'] as const)if(typeof body[key]==='string')values[key]=body[key].trim();if(!Object.keys(values).length)throw new ApiError('VALIDATION_ERROR','No editable fields supplied.');return c.json({invoice:await r.update('invoices',x.organisationId,c.req.param('id'),values)});});
accountsRoutes.post('/accounts/invoices',async c=>{const x=c.get('agentContext'),body=await c.req.json<any>();if(!body.contact_id||!body.invoice_number||!body.due_date||!body.total_amount)throw new ApiError('VALIDATION_ERROR','Invoice fields are incomplete.');return c.json({invoice:await c.get('runtimeRepository').insert('invoices',x.organisationId,{contact_id:body.contact_id,invoice_number:body.invoice_number,issue_date:body.issue_date??new Date().toISOString().slice(0,10),due_date:body.due_date,currency:body.currency??'ZAR',total_amount:body.total_amount,status:body.status??'issued',notes:body.notes??''})},201);});
accountsRoutes.post('/accounts/invoices/:id/payments',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),invoice:any=(await r.list('invoices',x.organisationId,{id:c.req.param('id')}))[0],body=await c.req.json<any>();if(!invoice||!body.amount)throw new ApiError('VALIDATION_ERROR','Invoice or payment amount is invalid.');const payment=await r.insert('invoice_payments',x.organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,amount:body.amount,payment_date:body.payment_date??new Date().toISOString().slice(0,10),payment_method:body.payment_method??null,payment_reference:body.payment_reference??null,status:'confirmed'});const promises:any[]=await r.list('promise_to_pay',x.organisationId,{invoice_id:invoice.id,status:'active'});for(const promise of promises){const payments:any[]=await r.list('invoice_payments',x.organisationId,{invoice_id:invoice.id,status:'confirmed'});const paid=payments.reduce((sum,p)=>sum+Number(p.amount),0);if(paid>=Number(promise.promised_amount)){await r.update('promise_to_pay',x.organisationId,promise.id,{status:'fulfilled'});await r.insert('collection_activity',x.organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,activity_type:'promise_fulfilled',metadata:{source:'system'}});}}await r.insert('audit_logs',x.organisationId,{actor_user_id:x.userId,event_type:'payment_recorded',entity_type:'invoice_payment',entity_id:(payment as any).id,metadata:{actor_type:'user',invoice_id:invoice.id}});return c.json({payment,activity:await r.insert('collection_activity',x.organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,activity_type:'payment_received',metadata:{source:'authenticated_user'}})});});
accountsRoutes.get('/accounts/policy',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository');return c.json({policy:(await r.list('collection_policies',x.organisationId))[0]??null});});
accountsRoutes.patch('/accounts/policy',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),body=await c.req.json<any>(),existing:any=(await r.list('collection_policies',x.organisationId))[0];const values:any={};for(const key of ['reminder_before_due_days','reminder_after_due_days','maximum_automatic_reminders','automatic_sending_enabled','final_demand_requires_approval','tone'] as const)if(body[key]!==undefined)values[key]=body[key];const policy=existing?await r.update('collection_policies',x.organisationId,existing.id,values):await r.insert('collection_policies',x.organisationId,values);return c.json({policy});});
accountsRoutes.post('/agents/accounts/run',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),agents=await r.list('agents',x.organisationId,{agent_type_key:'accounts_collections_agent',status:'active'});if(!agents[0])throw new ApiError('AGENT_NOT_READY','Accounts Agent is not active.');const body=await c.req.json<{invoiceId?:string}>();return c.json(await runAccountsAgent(r,c.env,x.organisationId,agents[0],body),202);});
accountsRoutes.get('/agents/accounts',async c=>{const x=c.get('agentContext'),rows=await c.get('runtimeRepository').list('agents',x.organisationId,{agent_type_key:'accounts_collections_agent'});return c.json({agent:rows[0]??null});});
accountsRoutes.post('/agents/accounts/status',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),body=await c.req.json<{status?:string}>();if(body.status!=='active'&&body.status!=='paused')throw new ApiError('VALIDATION_ERROR','Status must be active or paused.');const rows:any[]=await r.list('agents',x.organisationId,{agent_type_key:'accounts_collections_agent'});if(!rows[0])throw new ApiError('NOT_FOUND','Accounts Agent not found.');return c.json({agent:await r.update('agents',x.organisationId,rows[0].id,{status:body.status})});});
accountsRoutes.post('/accounts/invoices/:id/dispute',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository'),invoice:any=(await r.list('invoices',x.organisationId,{id:c.req.param('id')}))[0],body=await c.req.json<{reason?:string}>();if(!invoice)throw new ApiError('NOT_FOUND','Invoice not found.');const reason=body.reason?.trim();if(!reason||reason.length>300)throw new ApiError('VALIDATION_ERROR','A bounded dispute reason is required.');const updated=await r.update('invoices',x.organisationId,invoice.id,{disputed:true});const activity=await r.insert('collection_activity',x.organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,activity_type:'dispute_raised',metadata:{reason,source:'authenticated_user'}});return c.json({invoice:updated,activity});});
accountsRoutes.get('/approvals',async c=>{const x=c.get('agentContext');if(!['owner','admin','manager'].includes(x.role))throw new ApiError('FORBIDDEN','Approval permission required.');return c.json({approvals:await c.get('runtimeRepository').list('approvals',x.organisationId)});});
accountsRoutes.post('/approvals/:id/resolve',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository');if(!['owner','admin','manager'].includes(x.role))throw new ApiError('FORBIDDEN','Approval permission required.');const body=await c.req.json<{decision?:'approved'|'rejected';note?:string}>();if(body.decision!=='approved'&&body.decision!=='rejected')throw new ApiError('VALIDATION_ERROR','Decision must be approved or rejected.');const rows:any[]=await r.list('approvals',x.organisationId,{id:c.req.param('id')});if(!rows[0]||rows[0].status!=='pending')throw new ApiError('VALIDATION_ERROR','Approval is no longer pending.');const approval:any=rows[0],actions:any[]=await r.list('agent_actions',x.organisationId,{id:approval.agent_action_id}),action:any=actions[0];if(!action)throw new ApiError('NOT_FOUND','Approval action not found.');if(body.decision==='rejected'){await r.update('agent_actions',x.organisationId,action.id,{status:'rejected'});const updated=await r.update('approvals',x.organisationId,approval.id,{status:'rejected',decided_by:x.userId,decision_note:(body.note??'').slice(0,300),decided_at:new Date().toISOString()});await r.insert('collection_activity',x.organisationId,{invoice_id:action.input_payload?.invoice_id??null,activity_type:'approval_rejected',metadata:{action_id:action.id,source:'user'}});await r.insert('audit_logs',x.organisationId,{actor_user_id:x.userId,event_type:'accounts_approval_rejected',entity_type:'approval',entity_id:approval.id,metadata:{actor_type:'user',action_id:action.id}});return c.json({approval:updated});}
 const invoiceId=action.input_payload?.invoice_id;const invoice:any=(await r.list('invoices',x.organisationId,{id:invoiceId}))[0];const agent:any=(await r.list('agents',x.organisationId,{id:action.agent_id,agent_type_key:'accounts_collections_agent',status:'active'}))[0];const policy:any=(await r.list('collection_policies',x.organisationId))[0]??{};if(!invoice||invoice.status==='cancelled'||invoice.disputed||!agent) {await r.update('agent_actions',x.organisationId,action.id,{status:'cancelled',result_payload:{reason:'stale_financial_state'}});await r.update('approvals',x.organisationId,approval.id,{status:'approved',decided_by:x.userId,decided_at:new Date().toISOString()});await r.insert('collection_activity',x.organisationId,{invoice_id:invoiceId,activity_type:'approval_suppressed',metadata:{reason:'stale_financial_state'}});return c.json({status:'suppressed'});}const payments:any[]=await r.list('invoice_payments',x.organisationId,{invoice_id:invoice.id,status:'confirmed'}),paid=payments.reduce((n,p)=>n+Number(p.amount),0),outstanding=Number(invoice.total_amount)-paid;if(outstanding<=0){await r.update('agent_actions',x.organisationId,action.id,{status:'cancelled',result_payload:{reason:'invoice_paid'}});await r.update('approvals',x.organisationId,approval.id,{status:'approved',decided_by:x.userId,decided_at:new Date().toISOString()});return c.json({status:'suppressed',reason:'invoice_paid'});}const activities:any[]=await r.list('collection_activity',x.organisationId,{invoice_id:invoice.id}),stage=collectionStage({...invoice,outstanding_balance:outstanding},policy,activities.filter(a=>a.activity_type==='reminder_sent').length);if(stage!==action.input_payload?.stage||stage==='resolved'||stage==='final_review'){await r.update('agent_actions',x.organisationId,action.id,{status:'cancelled',result_payload:{reason:'stage_changed',current_stage:stage}});await r.update('approvals',x.organisationId,approval.id,{status:'approved',decided_by:x.userId,decided_at:new Date().toISOString()});return c.json({status:'suppressed',reason:'stage_changed',stage});}const contacts:any[]=await r.list('crm_contacts',x.organisationId,{id:invoice.contact_id}),contact:any=contacts[0],message=`Payment reminder for invoice ${invoice.invoice_number}, outstanding balance ${outstanding.toFixed(2)} ${invoice.currency}, due ${invoice.due_date}.`;const delivery=await new WhatsAppCollectionReminderDelivery(r).send({organisationId:x.organisationId,contactId:invoice.contact_id,invoiceId:invoice.id,message,agentId:agent.id,env:c.env});await r.update('approvals',x.organisationId,approval.id,{status:'approved',decided_by:x.userId,decided_at:new Date().toISOString()});if(delivery.status==='sent'){await r.update('agent_actions',x.organisationId,action.id,{status:'succeeded',result_payload:{status:'sent',channel:'whatsapp'}});await r.insert('collection_activity',x.organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,activity_type:'reminder_sent',stage,metadata:{source:'approved_agent_action',action_id:action.id}});}else{await r.update('agent_actions',x.organisationId,action.id,{status:'failed',result_payload:{status:delivery.status,reason:delivery.reason}});await r.insert('collection_activity',x.organisationId,{invoice_id:invoice.id,contact_id:invoice.contact_id,activity_type:'reminder_failed',stage,metadata:{source:'approved_agent_action',action_id:action.id,reason:delivery.reason}});}await r.insert('audit_logs',x.organisationId,{actor_user_id:x.userId,event_type:'accounts_approval_approved',entity_type:'approval',entity_id:approval.id,metadata:{actor_type:'user',action_id:action.id,execution:delivery.status}});return c.json({approval,delivery});});

