export type EmailDecisionType='reply'|'draft_for_approval'|'clarification'|'escalation'|'no_response'|'human_takeover'|'failure'; export type EmailCategory='enquiry'|'support'|'complaint'|'sales'|'payment_accounts'|'appointment'|'partnership'|'tender_procurement'|'spam_irrelevant'|'unclear'; export type EmailDecision={type:EmailDecisionType;category:EmailCategory;urgency:'normal'|'priority'|'escalation_required';confidence:'high'|'medium'|'low';subject?:string;body?:string;approvalRequired:boolean;approvalReason?:string;escalationReason?:string;humanInputRequired:boolean;};
export function parseEmailDecision(value:unknown):EmailDecision{const v=value as any;if(!v||!['reply','draft_for_approval','clarification','escalation','no_response','human_takeover','failure'].includes(v.decision)||!['high','medium','low'].includes(v.confidence)||!['normal','priority','escalation_required'].includes(v.urgency)||!['enquiry','support','complaint','sales','payment_accounts','appointment','partnership','tender_procurement','spam_irrelevant','unclear'].includes(v.category))throw new Error('INVALID_EMAIL_DECISION');const needsBody=['reply','draft_for_approval','clarification'].includes(v.decision);if(needsBody&&(typeof v.body!=='string'||!v.body.trim()||v.body.length>4000))throw new Error('INVALID_EMAIL_DECISION_BODY');return {type:v.decision,category:v.category,urgency:v.urgency,confidence:v.confidence,subject:typeof v.subject==='string'?v.subject.slice(0,300):undefined,body:v.body?.trim(),approvalRequired:v.approvalRequired===true,approvalReason:typeof v.approvalReason==='string'?v.approvalReason.slice(0,300):undefined,escalationReason:typeof v.escalationReason==='string'?v.escalationReason.slice(0,300):undefined,humanInputRequired:v.humanInputRequired===true};}
