import { SupabaseRuntimeRepository } from './supabase_repository';
export type CollectionStage='not_due'|'upcoming'|'due'|'overdue_1'|'overdue_2'|'final_review'|'escalated'|'resolved';
export async function getCustomerAccount(repo:SupabaseRuntimeRepository,organisationId:string,contactId:string){const invoices:any[]=await repo.list('invoices',organisationId,{contact_id:contactId}),payments:any[]=await repo.list('invoice_payments',organisationId,{contact_id:contactId}),paid=new Map<string,number>();for(const p of payments)if(p.status==='confirmed')paid.set(p.invoice_id,(paid.get(p.invoice_id)??0)+Number(p.amount));const today=new Date().toISOString().slice(0,10);return {invoices:invoices.map(i=>({...i,amount_paid:paid.get(i.id)??0,outstanding_balance:Math.max(0,Number(i.total_amount)-(paid.get(i.id)??0)),overdue:Number(i.total_amount)-(paid.get(i.id)??0)>0&&i.due_date<today&&i.status!=='cancelled'})),payments};}
export function collectionStage(invoice:any,policy:any,successfulReminders=0,now=new Date()):CollectionStage{const balance=Number(invoice.outstanding_balance??invoice.total_amount);if(invoice.status==='cancelled'||balance<=0)return 'resolved';const due=new Date(`${invoice.due_date}T00:00:00Z`);const today=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()));const days=Math.floor((today.getTime()-due.getTime())/86400000);if(days<0)return days>=-(policy.reminder_before_due_days??3)?'upcoming':'not_due';if(days===0)return 'due';if(successfulReminders>=Number(policy.maximum_automatic_reminders??2))return 'final_review';return successfulReminders===0?'overdue_1':'overdue_2';}
export async function findCollectionWorkDue(repo:SupabaseRuntimeRepository,organisationId:string,now=new Date()){const rows:any[]=await repo.list('invoices',organisationId),policy:any=(await repo.list('collection_policies',organisationId))[0]??{},activities:any[]=await repo.list('collection_activity',organisationId),promises:any[]=await repo.list('promise_to_pay',organisationId);return rows.map(i=>{const reminders=activities.filter(a=>a.invoice_id===i.id&&a.activity_type==='reminder_sent');const paid=0;const broken=promises.some(p=>p.invoice_id===i.id&&p.status==='active'&&p.promised_date<now.toISOString().slice(0,10));return {...i,outstanding_balance:Math.max(0,Number(i.total_amount)-paid),stage:collectionStage(i,policy,reminders.length,now),reminderCount:reminders.length,brokenPromise:broken};}).filter(i=>!['not_due','resolved'].includes(i.stage)&&!i.disputed);}
export function registerAccountsAgentType(){return 'accounts_collections_agent';}
