import { Hono } from 'hono';import { AppEnv,ApiError } from '../api_types';import { authMiddleware } from '../middleware/auth';import { planCatalogue,resolveEntitlements } from '../billing/entitlements';export const billingRoutes=new Hono<AppEnv>();billingRoutes.use('*',authMiddleware);billingRoutes.get('/billing/plans',c=>c.json({plans:planCatalogue}));billingRoutes.get('/billing/status',async c=>{const x=c.get('agentContext'),data=await resolveEntitlements(c.get('runtimeRepository'),x.organisationId);return c.json({...data,billingProvider:{configured:false,status:'unconfigured',message:'Billing provider is not configured.'}});});billingRoutes.post('/billing/checkout',async _=>{throw new ApiError('INTERNAL_ERROR','Billing provider is not configured.',503);});
