import { Hono } from 'hono';import { AppEnv } from '../api_types';import { authMiddleware } from '../middleware/auth';
export const workforceRoutes=new Hono<AppEnv>();workforceRoutes.use('*',authMiddleware);const names:any={business_assistant:'Business Assistant',whatsapp_agent:'WhatsApp Agent',accounts_collections_agent:'Accounts & Collections',tender_agent:'Tender Agent',email_agent:'Email Agent',voice_receptionist:'Voice Receptionist'};const routes:any={business_assistant:'/agents/business-assistant',whatsapp_agent:'/agents/whatsapp',accounts_collections_agent:'/agents/accounts',tender_agent:'/tenders',email_agent:'/agents/email',voice_receptionist:'/agents/voice'};
workforceRoutes.get('/workforce/summary',async c=>{const x=c.get('agentContext'),r=c.get('runtimeRepository');const [agents,runs,actions,approvals,audit,usage]=await Promise.all([r.list('agents',x.organisationId),r.list('agent_runs',x.organisationId),r.list('agent_actions',x.organisationId),r.list('approvals',x.organisationId),r.list('audit_logs',x.organisationId),r.list('ai_usage_events',x.organisationId)]);const employees=(agents as any[]).filter(a=>names[a.agent_type_key]).map(a=>{const own=(runs as any[]).filter(v=>v.agent_id===a.id).sort((l,v)=>String(v.created_at??'').localeCompare(String(l.created_at??'')));const latest=own[0];const pending=(actions as any[]).filter(v=>v.agent_id===a.id&&v.status==='approval_pending').length;return {id:a.id,type:a.agent_type_key,name:names[a.agent_type_key],status:a.status,route:routes[a.agent_type_key],latestRun:latest?{status:latest.status,time:latest.finished_at??latest.created_at,error:latest.error_code??null}:null,pendingApprovals:pending,integration:a.agent_type_key==='email_agent'||a.agent_type_key==='voice_receptionist'?'disconnected':null};});const pending=(approvals as any[]).filter(a=>['pending','requested'].includes(String(a.status))).length;const failures=(runs as any[]).filter(a=>a.status==='failed').sort((l,v)=>String(v.created_at??'').localeCompare(String(l.created_at??''))).slice(0,8).map(v=>({agentId:v.agent_id,error:v.error_code??'Run failed',time:v.finished_at??v.created_at}));return c.json({employees,pendingApprovals:pending,recentFailures:failures,recentActivity:(audit as any[]).slice(-10).reverse().map(v=>({event:v.event_type,time:v.created_at,entity:v.entity_type})),usageSummary:{requests:(usage as any[]).length}});});
