import { SupabaseRuntimeRepository } from './supabase_repository';import { MetaWhatsAppCloudProvider } from '../whatsapp/provider';
export interface CollectionReminderDeliveryResult{status:'sent'|'unavailable'|'provider_restriction'|'failed';messageId?:string;reason?:string;}
export interface CollectionReminderDelivery{send(input:{organisationId:string;contactId:string;invoiceId:string;message:string;agentId:string;env:any}):Promise<CollectionReminderDeliveryResult>}
export class WhatsAppCollectionReminderDelivery implements CollectionReminderDelivery{constructor(private readonly repo:SupabaseRuntimeRepository){}async send(input:{organisationId:string;contactId:string;invoiceId:string;message:string;agentId:string;env:any}):Promise<CollectionReminderDeliveryResult>{const contacts:any[]=await this.repo.list('crm_contacts',input.organisationId,{id:input.contactId}),contact=contacts[0];const integrations:any[]=await this.repo.list('organisation_integrations',input.organisationId,{provider:'meta_whatsapp',status:'connected'}),integration=integrations[0];if(!contact?.whatsapp_number)return {status:'unavailable',reason:'CONTACT_WHATSAPP_UNAVAILABLE'};if(!integration?.phone_number_id)return {status:'unavailable',reason:'WHATSAPP_INTEGRATION_UNAVAILABLE'};const conversations:any[]=await this.repo.list('unified_conversations',input.organisationId,{contact_id:input.contactId,channel_key:'whatsapp'});const conversation=conversations[0]??await this.repo.insert('unified_conversations',input.organisationId,{contact_id:input.contactId,channel_key:'whatsapp',status:'open'});const outbound:any=await this.repo.insert('unified_messages',input.organisationId,{conversation_id:conversation.id,channel_key:'whatsapp',direction:'outbound',recipient:contact.whatsapp_number,content:input.message,message_type:'text',delivery_status:'pending',agent_generated:true,metadata:{agent_id:input.agentId,collection_invoice_id:input.invoiceId}});try{const sent=await new MetaWhatsAppCloudProvider(input.env.META_WHATSAPP_ACCESS_TOKEN,input.env.META_GRAPH_API_VERSION??'v23.0').sendText(integration.phone_number_id,contact.whatsapp_number,input.message);await this.repo.update('unified_messages',input.organisationId,outbound.id,{external_message_id:sent.providerMessageId,delivery_status:sent.status});await this.repo.update('unified_conversations',input.organisationId,conversation.id,{last_activity_at:new Date().toISOString()});return {status:'sent',messageId:outbound.id};}catch(error){await this.repo.update('unified_messages',input.organisationId,outbound.id,{delivery_status:'failed',metadata:{error_code:error instanceof Error?error.message:'WHATSAPP_SEND_FAILED'}});return {status:'failed',reason:'WHATSAPP_SEND_FAILED'};}}}
