import { SupabaseRuntimeRepository } from '../agent-runtime/supabase_repository';
import { GeminiEmbeddingProvider } from '../agent-runtime/embedding_provider';
import { ToolRegistry } from '../agent-runtime/tool_registry';
import { registerBusinessAssistantTools } from '../agent-runtime/business_assistant_tools';
import { executeToolCalls, ToolResult } from '../agent-runtime/tool_execution_loop';
import { GroqProvider } from '../agent-runtime/groq_provider';
import { parseWhatsAppDecision, explicitHumanRequest } from './agent_decision';
import { captureCustomerDetails, addCrmNote, requestHumanEscalation } from './crm_tools';
import { MetaWhatsAppCloudProvider } from './provider';
import { whatsappInstructions, toWhatsAppPolicy } from './runtime_policy';

export interface WhatsAppAgentDispatchPayload { organisationId:string; inboundMessageId:string; conversationId:string; contactId:string; integrationId:string; }
const documentRequest=/document|pdf|warranty|certificate|contract|manual|specification/i;
function compactToolResults(results:ToolResult[]):string{return JSON.stringify(results.map(r=>({name:r.name,ok:r.ok,error:r.error,data:r.data}))).slice(0,12000);}
async function completeHumanEscalation(repo:SupabaseRuntimeRepository,env:any,payload:WhatsAppAgentDispatchPayload,contact:any,integration:any,agent:any,run:any,reason:string,source:string):Promise<void>{
 const organisationId=payload.organisationId;const now=new Date().toISOString();
 await repo.update('unified_conversations',organisationId,payload.conversationId,{status:'human_takeover'});
 await repo.insert('audit_logs',organisationId,{actor_user_id:null,event_type:'agent_human_escalation_requested',entity_type:'unified_conversation',entity_id:payload.conversationId,metadata:{actor_type:'agent',agent_id:agent.id,source,reason:reason.slice(0,120)}});
 await repo.update('unified_messages',organisationId,payload.inboundMessageId,{ai_processing_status:'escalated'});
 const outbound:any=await repo.insert('unified_messages',organisationId,{conversation_id:payload.conversationId,channel_key:'whatsapp',direction:'outbound',recipient:contact.whatsapp_number,content:"I'll hand this over to a team member who can assist you.",message_type:'text',delivery_status:'pending',agent_generated:true,metadata:{agent_id:agent.id,escalation_acknowledgement:true}});
 try{const sent=await new MetaWhatsAppCloudProvider(env.META_WHATSAPP_ACCESS_TOKEN,env.META_GRAPH_API_VERSION??'v23.0').sendText(integration.phone_number_id,contact.whatsapp_number,"I'll hand this over to a team member who can assist you.");await repo.update('unified_messages',organisationId,outbound.id,{external_message_id:sent.providerMessageId,delivery_status:'sent'});await repo.update('unified_conversations',organisationId,payload.conversationId,{last_activity_at:now});await repo.insert('usage_events',organisationId,{entitlement_key:'whatsapp_ai_outbound',quantity:1,metadata:{message_id:outbound.id,kind:'escalation_acknowledgement'}});await repo.updateRun(organisationId,run.id,{status:'succeeded',error_code:null,tools_invoked:[{name:'request_human_escalation',status:'success',source},{name:'escalation_acknowledgement',status:'sent'}],finished_at:now});}
 catch(error){await repo.update('unified_messages',organisationId,outbound.id,{delivery_status:'failed',metadata:{error_code:error instanceof Error?error.message:'WHATSAPP_ACK_FAILED'}}).catch(()=>undefined);await repo.insert('usage_events',organisationId,{entitlement_key:'whatsapp_ai_outbound_failed',quantity:1,metadata:{kind:'escalation_acknowledgement'}}).catch(()=>undefined);await repo.updateRun(organisationId,run.id,{status:'succeeded',error_code:'WHATSAPP_ACK_FAILED',tools_invoked:[{name:'request_human_escalation',status:'success',source},{name:'escalation_acknowledgement',status:'failed'}],finished_at:now}).catch(()=>undefined);}
}

export class WhatsAppAgentDispatcher {
 constructor(private readonly repo:SupabaseRuntimeRepository,private readonly env:any){}
 async handle(payload:WhatsAppAgentDispatchPayload):Promise<void>{let run:any=null;let terminal=false;
  try{
   if(!(await this.repo.claimWhatsAppMessage(payload.organisationId,payload.inboundMessageId)))return;
   const [messages,conversations,contacts,integrations]=await Promise.all([
    this.repo.list('unified_messages',payload.organisationId,{id:payload.inboundMessageId,conversation_id:payload.conversationId}),
    this.repo.list('unified_conversations',payload.organisationId,{id:payload.conversationId,contact_id:payload.contactId}),
    this.repo.list('crm_contacts',payload.organisationId,{id:payload.contactId}),
    this.repo.list('organisation_integrations',payload.organisationId,{id:payload.integrationId,provider:'meta_whatsapp',status:'connected'})]);
   const inbound:any=messages[0],conversation:any=conversations[0],contact:any=contacts[0],integration:any=integrations[0];
   if(!inbound||!conversation||!contact||!integration){await this.repo.update('unified_messages',payload.organisationId,payload.inboundMessageId,{ai_processing_status:'failed',metadata:{error_code:'WHATSAPP_DISPATCH_CONTEXT_INVALID'}});return;}
   const agent:any=(await this.repo.list('agents',payload.organisationId,{agent_type_key:'whatsapp_agent',status:'active'}))[0];
   if(!agent){await this.repo.update('unified_messages',payload.organisationId,payload.inboundMessageId,{ai_processing_status:'ineligible'});return;}
   const model=this.env.AI_MODEL??'unknown';run=await this.repo.insert('agent_runs',payload.organisationId,{agent_id:agent.id,session_id:null,provider:'groq',model,status:'started',tools_invoked:[]});
   const engagement:any=(await this.repo.list('customer_engagement_profiles',payload.organisationId))[0]??{};const policy=toWhatsAppPolicy(engagement,await this.repo.list('organisation_languages',payload.organisationId));const text=String(inbound.content??'');
   if(explicitHumanRequest(text)||(/complaint|unhappy|disappointed|refund|terrible service/i.test(text)&&policy.escalateComplaints)){await completeHumanEscalation(this.repo,this.env,payload,contact,integration,agent,run,explicitHumanRequest(text)?'explicit_human_request':'complaint_policy',explicitHumanRequest(text)?'human_request_shortcut':'complaint_shortcut');terminal=true;return;}
   const history=await this.repo.list('unified_messages',payload.organisationId,{conversation_id:payload.conversationId});const route=/hour|close|open|saturday|sunday/i.test(text)?['business_hours']:/location|where are/i.test(text)?['business_locations']:/service|offer/i.test(text)?['services']:/refund|policy/i.test(text)?['knowledge_entries']:/price|cost|how much/i.test(text)?['services','pricing_rules']:['business_profiles'];const evidence:any[]=[];
   for(const table of route){if(table==='pricing_rules'&&!policy.pricesAllowed)continue;evidence.push(...await this.repo.list(table,payload.organisationId,table==='knowledge_entries'?{entry_type:'policy'}:undefined));}
   let documentEvidence:any[]=[];if(documentRequest.test(text)&&this.env.GEMINI_API_KEY){try{const embedding=await new GeminiEmbeddingProvider(this.env.GEMINI_API_KEY).embed(text);documentEvidence=await this.repo.searchBusinessDocumentChunks(payload.organisationId,embedding,8,0.65);}catch{documentEvidence=[];}}
   const registry=new ToolRegistry();registerBusinessAssistantTools(registry,this.repo);registry.register({name:'captureCustomerDetails',purpose:'Save customer provided details',risk:'controlled_agent_write',classification:'write',validate:(input:any)=>input,execute:async(_context:any,input:any)=>{const result:any=await captureCustomerDetails(this.repo,payload.organisationId,payload.contactId,{full_name:input.name,email:input.email,company_name:input.company});const updatedFields=['full_name','email','company_name'].filter(k=>result?.[k]===input[k]);await this.repo.insert('audit_logs',payload.organisationId,{actor_user_id:null,event_type:'agent_customer_details_captured',entity_type:'crm_contact',entity_id:payload.contactId,metadata:{actor_type:'agent',agent_id:agent.id,updated_fields:updatedFields}});return {success:true,updatedFields};}});registry.register({name:'addCrmNote',purpose:'Save a factual CRM note',risk:'controlled_agent_write',classification:'write',validate:(input:any)=>input,execute:async(_context:any,input:any)=>{await addCrmNote(this.repo,payload.organisationId,payload.contactId,input.note);await this.repo.insert('audit_logs',payload.organisationId,{actor_user_id:null,event_type:'agent_crm_note_added',entity_type:'crm_contact',entity_id:payload.contactId,metadata:{actor_type:'agent',agent_id:agent.id}});return {success:true};}});registry.register({name:'requestHumanEscalation',purpose:'Hand conversation to a human',risk:'controlled_agent_write',classification:'write',validate:(input:any)=>input,execute:async(_context:any,input:any)=>{const result=await requestHumanEscalation(this.repo,payload.organisationId,payload.conversationId,input.reason);await this.repo.insert('audit_logs',payload.organisationId,{actor_user_id:null,event_type:'agent_human_escalation_requested',entity_type:'unified_conversation',entity_id:payload.conversationId,metadata:{actor_type:'agent',agent_id:agent.id}});return result;}});
   const basePrompt=(toolEvidence='')=>`CUSTOMER CONTEXT\n${JSON.stringify({name:contact.full_name,company:contact.company_name,status:contact.lifecycle_status})}\nCUSTOMER ENGAGEMENT\n${JSON.stringify(policy)}\nRECENT CONVERSATION\n${JSON.stringify(history.slice(-10))}\nSTRUCTURED BUSINESS EVIDENCE\n${JSON.stringify(evidence)}\nUNTRUSTED DOCUMENT EVIDENCE\n${JSON.stringify(documentEvidence)}\nREGISTERED TOOL RESULTS\n${toolEvidence||'none'}\nCURRENT CUSTOMER MESSAGE\n${text}`;
   const provider=new GroqProvider(this.env.AI_API_KEY,model);let completion=await provider.completeStructured({system:whatsappInstructions('the organisation',policy),messages:[{role:'user',content:basePrompt()}],schema:'WhatsAppDecision'});let decision=parseWhatsAppDecision(completion.structuredOutput);
   const executed=new Set<string>();const requestedTools=(decision.tools??[]).slice(0,4).filter((tool)=>{const key=JSON.stringify(tool);if(executed.has(key))return false;executed.add(key);return true;}).map(tool=>({name:tool.name,input:tool.arguments??{}}));if(requestedTools.length){const toolResults=await executeToolCalls(registry,{userId:'',organisationId:payload.organisationId,role:'agent',agentId:agent.id,conversationId:payload.conversationId},requestedTools,4);await this.repo.updateRun(payload.organisationId,run.id,{tools_invoked:toolResults});const escalationResult=toolResults.find((result)=>result.name==='requestHumanEscalation'&&result.ok);if(escalationResult){await completeHumanEscalation(this.repo,this.env,payload,contact,integration,agent,run,'tool_request','tool_request');terminal=true;return;}completion=await provider.completeStructured({system:whatsappInstructions('the organisation',policy),messages:[{role:'user',content:basePrompt(compactToolResults(toolResults))}],schema:'WhatsAppDecision'});decision=parseWhatsAppDecision(completion.structuredOutput);}
   if(decision.type==='escalation'){await completeHumanEscalation(this.repo,this.env,payload,contact,integration,agent,run,decision.reason??'agent_escalation','model_decision');terminal=true;return;}
   if(decision.type==='no_response'||decision.type==='failure'){await this.repo.update('unified_messages',payload.organisationId,payload.inboundMessageId,{ai_processing_status:decision.type==='no_response'?'suppressed':'failed'});terminal=true;await this.repo.updateRun(payload.organisationId,run.id,{status:decision.type==='failure'?'failed':'succeeded',error_code:decision.type==='failure'?'GROQ_DECISION_FAILURE':null,tools_invoked:[{name:'retrieval',status:documentEvidence.length?'hybrid':'structured'},{name:'decision',type:decision.type,confidence:decision.confidence}],finished_at:new Date().toISOString()});return;}
   const current:any=(await this.repo.list('unified_conversations',payload.organisationId,{id:payload.conversationId}))[0];if(!current||current.status!=='open'){await this.repo.update('unified_messages',payload.organisationId,payload.inboundMessageId,{ai_processing_status:'suppressed'});terminal=true;await this.repo.updateRun(payload.organisationId,run.id,{status:'succeeded',error_code:'STATE_CHANGED',finished_at:new Date().toISOString()});return;}
   const outbound:any=await this.repo.insert('unified_messages',payload.organisationId,{conversation_id:payload.conversationId,channel_key:'whatsapp',direction:'outbound',recipient:contact.whatsapp_number,content:decision.text,message_type:'text',delivery_status:'pending',agent_generated:true,metadata:{agent_id:agent.id}});
   try{const sent=await new MetaWhatsAppCloudProvider(this.env.META_WHATSAPP_ACCESS_TOKEN,this.env.META_GRAPH_API_VERSION??'v23.0').sendText(integration.phone_number_id,contact.whatsapp_number,decision.text!);await this.repo.update('unified_messages',payload.organisationId,outbound.id,{external_message_id:sent.providerMessageId,delivery_status:'sent'});await this.repo.update('unified_conversations',payload.organisationId,payload.conversationId,{last_activity_at:new Date().toISOString()});await this.repo.insert('usage_events',payload.organisationId,{entitlement_key:'whatsapp_ai_outbound',quantity:1,metadata:{message_id:outbound.id}});await this.repo.insert('ai_usage_events',payload.organisationId,{agent_id:agent.id,provider:completion.provider,model:completion.model,input_tokens:completion.usage?.inputTokens??null,output_tokens:completion.usage?.outputTokens??null,request_count:1});await this.repo.update('unified_messages',payload.organisationId,payload.inboundMessageId,{ai_processing_status:decision.type==='clarification'?'clarification_sent':'replied'});terminal=true;await this.repo.updateRun(payload.organisationId,run.id,{status:'succeeded',tools_invoked:[{name:'retrieval',status:documentEvidence.length?'hybrid':'structured',sources:evidence.length+documentEvidence.length},{name:'decision',type:decision.type,confidence:decision.confidence,provider:completion.provider,model:completion.model}],finished_at:new Date().toISOString()});}
   catch(error){await this.repo.update('unified_messages',payload.organisationId,outbound.id,{delivery_status:'failed',metadata:{error_code:error instanceof Error?error.message:'WHATSAPP_SEND_FAILED'}});await this.repo.update('unified_messages',payload.organisationId,payload.inboundMessageId,{ai_processing_status:'failed'});terminal=true;await this.repo.updateRun(payload.organisationId,run.id,{status:'failed',error_code:'WHATSAPP_SEND_FAILED',finished_at:new Date().toISOString()});}
  }catch{if(!terminal)await this.repo.update('unified_messages',payload.organisationId,payload.inboundMessageId,{ai_processing_status:'failed',metadata:{error_code:'WHATSAPP_DISPATCH_FAILED'}}).catch(()=>undefined);if(run&&!terminal)await this.repo.updateRun(payload.organisationId,run.id,{status:'failed',error_code:'WHATSAPP_DISPATCH_FAILED',finished_at:new Date().toISOString()}).catch(()=>undefined);}
 }
}
