import { SupabaseRuntimeRepository } from '../agent-runtime/supabase_repository';
export async function captureCustomerDetails(repo:SupabaseRuntimeRepository,organisationId:string,contactId:string,details:{full_name?:string;company_name?:string;email?:string}) { const current:any=(await repo.list('crm_contacts',organisationId,{id:contactId}))[0]; if(!current)throw new Error('CONTACT_NOT_FOUND'); const allowed:any={}; for(const key of ['full_name','company_name','email'] as const)if(details[key]&&(!current[key]||String(current[key]).trim()===''))allowed[key]=details[key]; if(!Object.keys(allowed).length)return current; return repo.update('crm_contacts',organisationId,contactId,allowed); }
export async function addCrmNote(repo:SupabaseRuntimeRepository,organisationId:string,contactId:string,note:string){const clean=note.trim().slice(0,500);if(!clean||/[\n\r]/.test(clean))throw new Error('INVALID_NOTE');const current:any=(await repo.list('crm_contacts',organisationId,{id:contactId}))[0];return repo.update('crm_contacts',organisationId,contactId,{notes:[current?.notes,clean].filter(Boolean).join('\n')});}
export async function requestHumanEscalation(repo:SupabaseRuntimeRepository,organisationId:string,conversationId:string,reason:string){return repo.update('unified_conversations',organisationId,conversationId,{status:'human_takeover'}).then(()=>({status:'human_takeover',reason:reason.slice(0,120)}));}
