export type AccountsDecisionType='no_action'|'prepare_reminder'|'send_reminder'|'clarification'|'record_customer_update'|'escalation'|'failure';
export interface AccountsDecision { decision:AccountsDecisionType; confidence:'high'|'medium'|'low'; message?:string; reason?:string; approvalRequired:boolean; }
export function parseAccountsDecision(value:unknown):AccountsDecision{const v=value as any;if(!v||!['no_action','prepare_reminder','send_reminder','clarification','record_customer_update','escalation','failure'].includes(v.decision)||!['high','medium','low'].includes(v.confidence)||typeof v.approvalRequired!=='boolean')throw new Error('INVALID_ACCOUNTS_DECISION');if(v.message!==undefined&&(typeof v.message!=='string'||v.message.length>2000))throw new Error('INVALID_ACCOUNTS_DECISION');if(v.reason!==undefined&&(typeof v.reason!=='string'||v.reason.length>300))throw new Error('INVALID_ACCOUNTS_DECISION');return {decision:v.decision,confidence:v.confidence,message:v.message?.trim(),reason:v.reason?.trim(),approvalRequired:v.approvalRequired};}
