export type WhatsAppDecisionType = 'reply'|'clarification'|'escalation'|'no_response'|'failure';
export type WhatsAppReadToolName = 'get_company_profile'|'get_business_locations'|'get_business_hours'|'list_departments'|'search_business_contacts'|'get_escalation_contact'|'search_products'|'search_services'|'list_packages'|'get_pricing_rules'|'get_customer_engagement_profile'|'get_supported_languages'|'search_faqs'|'search_policies'|'list_business_documents';
export type WhatsAppToolRequest = {name:'captureCustomerDetails';arguments:{name?:string;email?:string;company?:string}}|{name:'addCrmNote';arguments:{note:string}}|{name:'requestHumanEscalation';arguments:{reason:string}}|{name:WhatsAppReadToolName;arguments?:Record<string,unknown>};
export interface WhatsAppDecision {type:WhatsAppDecisionType;text?:string;confidence:'high'|'medium'|'low';reason?:string;retrievalMode:'none'|'structured'|'document'|'hybrid';tools:WhatsAppToolRequest[];}
const readTools=new Set<string>(['get_company_profile','get_business_locations','get_business_hours','list_departments','search_business_contacts','get_escalation_contact','search_products','search_services','list_packages','get_pricing_rules','get_customer_engagement_profile','get_supported_languages','search_faqs','search_policies','list_business_documents']);const email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function boundedString(value:unknown,max:number,required=true):string|undefined{if(typeof value!=='string')throw new Error('INVALID_WHATSAPP_TOOL_ARGUMENTS');const result=value.trim();if(required&&!result)throw new Error('INVALID_WHATSAPP_TOOL_ARGUMENTS');if(result.length>max)throw new Error('INVALID_WHATSAPP_TOOL_ARGUMENTS');return result;}
function parseTool(raw:unknown):WhatsAppToolRequest{if(typeof raw==='string'){if(!readTools.has(raw))throw new Error('INVALID_WHATSAPP_TOOL');return {name:raw as WhatsAppReadToolName,arguments:{}};}const value=raw as any;if(!value||typeof value.name!=='string'||!('arguments' in value))throw new Error('INVALID_WHATSAPP_TOOL');const args=value.arguments;if(value.name==='captureCustomerDetails'){if(!args||typeof args!=='object')throw new Error('INVALID_WHATSAPP_TOOL_ARGUMENTS');const out:any={};for(const key of ['name','email','company'])if(key in args){const v=boundedString(args[key],200);if(v)out[key]=v;}if(!Object.keys(out).length||Object.keys(args).some((k)=>!['name','email','company'].includes(k)))throw new Error('INVALID_WHATSAPP_TOOL_ARGUMENTS');if(out.email&&!email.test(out.email))throw new Error('INVALID_WHATSAPP_TOOL_ARGUMENTS');return {name:value.name,arguments:out};}if(value.name==='addCrmNote'){if(Object.keys(args??{}).some(k=>k!=='note'))throw new Error('INVALID_WHATSAPP_TOOL_ARGUMENTS');return {name:value.name,arguments:{note:boundedString(args?.note,500)!}};}if(value.name==='requestHumanEscalation'){if(Object.keys(args??{}).some(k=>k!=='reason'))throw new Error('INVALID_WHATSAPP_TOOL_ARGUMENTS');return {name:value.name,arguments:{reason:boundedString(args?.reason,200)!}};}if(readTools.has(value.name)){if(args!==undefined&&(typeof args!=='object'||Array.isArray(args)))throw new Error('INVALID_WHATSAPP_TOOL_ARGUMENTS');return {name:value.name,arguments:args??{}};}throw new Error('INVALID_WHATSAPP_TOOL');}
export function parseWhatsAppDecision(value:unknown):WhatsAppDecision{const v=value as any;if(!v||!['reply','clarification','escalation','no_response','failure'].includes(v.decision)||!['high','medium','low'].includes(v.confidence))throw new Error('INVALID_WHATSAPP_DECISION');const needsText=v.decision==='reply'||v.decision==='clarification';if(needsText&&(typeof v.message!=='string'||!v.message.trim()||v.message.length>2000))throw new Error('INVALID_WHATSAPP_DECISION_MESSAGE');const rawTools=Array.isArray(v.tools)?v.tools.slice(0,8):[];return {type:v.decision,text:v.message?.trim(),confidence:v.confidence,reason:typeof v.escalationReason==='string'?v.escalationReason.slice(0,200):undefined,retrievalMode:'none',tools:rawTools.map(parseTool)};}
export function explicitHumanRequest(text:string):boolean{return /\b(speak|talk|transfer|connect).{0,20}\b(human|person|manager|someone)\b|human\s+agent/i.test(text);}
