export type VoiceDecision={action:'answer'|'ask_clarification'|'capture_lead'|'capture_message'|'appointment_request'|'escalate'|'transfer_required'|'no_action'|'failure';category:string;urgency:'normal'|'priority'|'escalation_required';response?:string;summary:string;escalationReason?:string;}; export function parseVoiceDecision(v:any):VoiceDecision{if(!v||!['answer','ask_clarification','capture_lead','capture_message','appointment_request','escalate','transfer_required','no_action','failure'].includes(v.action)||!['normal','priority','escalation_required'].includes(v.urgency)||typeof v.summary!=='string')throw new Error('INVALID_VOICE_DECISION');return {action:v.action,category:typeof v.category==='string'?v.category.slice(0,80):'unclear',urgency:v.urgency,response:typeof v.response==='string'?v.response.slice(0,2000):undefined,summary:v.summary.slice(0,1000),escalationReason:typeof v.escalationReason==='string'?v.escalationReason.slice(0,300):undefined};}
